ItemLocalData.tab = {
[100000] = {id = 100000, name = "能源晶體", icon = "icon_goods_nengyuanjingti", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "原初結晶經過研磨與提煉後的產物，呈六面體狀，便於後續地加工與使用。小小的一片，蘊藏著無限的可能。\n「真可惜，那麼大的結晶原礦最後只剩下這麼一些，真是浪費。」", group = 4998, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, "0", "0", "0"},
[100001] = {id = 100001, name = "盾幣", icon = "icon_goods_dunbi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "艾吉斯設立七大區後統一發行的貨幣，通行於世界。\n「艾吉斯於2000年發行的貨幣。」\n「是目前世界上唯一流通且合法的貨幣。」", group = 100, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, "0", "0", "0"},
[100002] = {id = 100002, name = "精英紀念幣", icon = "icon_goods_jingyingjinianbi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_yx_jyyx_01", txt = "參與精英演習後發放的紀念幣，可以在【精英商店】中購買物品。\n「完成了精英演習意味著——你們已經擁有踏足最前線的經驗與實力，還是那句老話……你們是我最驕傲的學生，別死了。」", group = 101, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, "0", "0", "0"},
[100003] = {id = 100003, name = "新銳紀念幣", icon = "icon_goods_xinruijinianbi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "參與新銳演習後發放的紀念幣，可以在【新銳商店】中購買物品。\n「恭喜你們通過新銳演習，自此以後你們就將踏上真正的戰場……活著回來見我。」", group = 102, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, "0", "0", "0"},
[100004] = {id = 100004, name = "討伐幣", icon = "icon_goods_taofabi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_lhtf_01", txt = "參與原罪聯合討伐後發放的貨幣，可以在【聯合商店】中購買物品。\n「——最近准罪級的原罪出現得有點頻繁，隊長預感到之後會有大事情要發生，她覺得現在調離前線也許是最好的選擇……但如果連最前線的我們都選擇逃避，大家該怎麼辦啊……不行……我們得留在這。」", group = 103, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, "0", "0", "0"},
[100005] = {id = 100005, name = "日用代幣", icon = "icon_goods_jiajubi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_jy_yzts_01", txt = "發放給領航與駕駛員的日用補貼代幣，可以在【後勤商店】中購買物品。\n「——哼♪~哼哼~~不用洗碗啦♪~我要購入一個洗碗機♪~\n這是某位駕駛員初次使用日用代幣選購傢俱的珍貴記錄，在這之後這段哼唱被大家廣為流傳，該駕駛員也被戲稱為“後勤店妖精”。」", group = 104, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, "0", "0", "0"},
[100006] = {id = 100006, name = "公會幣", icon = "icon_goods_gonghuibi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "獎勵給為公會做出貢獻的領航，可以在【公會供給】中購買物品。\n「願你前行的道路上不再孤單。」", group = 105, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, "0", "0", "0"},
[100007] = {id = 100007, name = "友情幣", icon = "icon_goods_youqingbi", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_wjxq_zyjs_01", txt = "獎勵多次在戰場上幫助同僚的領航，可以在【友情商店】中購買物品。\n「願你在困境中有人相助。」", group = 106, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, "0", "0", "0"},
[100008] = {id = 100008, name = "原初結晶", icon = "icon_goods_yuanchujiejing", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_sc_cz_01", txt = "從原初尼姆比斯結晶中開採出的礦石，較為稀少。\n「結晶一旦被開採出來，便會被用於製作幻化核心。」\n「市面上很少有流通在外的結晶。」", group = 4999, itemstar = 0, describe = "0", costeffect = "0", sort = 1, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110000] = {id = 110000, name = "稀釋能量合劑", icon = "icon_goods_tiliyaoji_2", quality = 2, use = 1, fall = "4_100001_30", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "稀釋能量合劑，使用後可恢復30點體力。\n「稀釋的尼姆比斯合劑，可以稍微緩解過度使用【通感】帶來的無力感。有水蜜桃和甜橙兩種口味，即使普通人誤飲也沒有危害。」", group = 4001, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110001] = {id = 110001, name = "常規能量合劑", icon = "icon_goods_tiliyaoji_0", quality = 3, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "常規能量合劑，使用後可恢復50點體力。\n「史蒂芬妮博士特製的尼姆比斯合劑。\n吉雅的身邊時常配備著三瓶。比稀釋合劑多了一種酸酸的口味，似乎是根據吉雅的要求調配的。」", group = 4002, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110002] = {id = 110002, name = "濃縮能量合劑", icon = "icon_goods_tiliyaoji_1", quality = 4, use = 1, fall = "4_100001_100", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "濃縮能量合劑，使用後可恢復100點體力。\n「快速補充使用【通感】而消耗的精神力與體力，扭轉戰局的關鍵，需要注意的是，史蒂芬妮博士在其中加入了大量的提神藥物，在非戰鬥狀態下飲用可能會導致徹夜不眠。」", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110010] = {id = 110010, name = "幻化星碎", icon = "icon_goods_shengxingsuipian", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "蘊含著巨大的能量，可用於提升角色的星級。\n「【適格率】只是決定駕駛員的起點，但一位駕駛員最終站在什麼高度，往往與【適格率】沒有什麼關係。」", group = 3000, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110020] = {id = 110020, name = "共鳴原石", icon = "icon_goods_gongmingyuanshi", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_sc_wzbc_01", txt = "可用於製造共鳴裝備。\n「當駕駛員常用的武裝不足以應對更高級的原罪時，也許你會需要這個……共鳴原石不是消失了，它只是換了一種樣子陪在駕駛員的身邊。」", group = 3001, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110021] = {id = 110021, name = "共鳴結晶體", icon = "icon_goods_gongmingjiejingti", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_bj_gmzb_01", txt = "從幻化核心中提煉出的副產物，可用於強化共鳴裝備。\n「我把背包中的共鳴結晶體與駕駛員身上的裝備進行共鳴強化！」", group = 3002, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110030] = {id = 110030, name = "定向調度券", icon = "icon_goods_putongzhaomujuan", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "用於徵調AVG駕駛員。\n「您想要與怎樣的人相遇，想與她們如何相處，這都取決於您的想法，領航。」", group = 4100, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110031] = {id = 110031, name = "精英調度券", icon = "icon_goods_jingyingzhaomujuan", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "可以徵調不同尋常的駕駛員。\n「不同尋常——代表著駕駛員在某些方面擁有著特別優秀的能力。」\n「不同尋常——可能也代表著這位駕駛員有著某種缺陷。」\n「不過我相信，如果是你的話，一定能引領她們找到正確的道路……請時刻謹記，這些為世界挺身而出、身經百戰的駕駛員，她們是英雄，她們是戰士，同時也是富有複雜情感的、正在成長的女孩。」", group = 4101, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110032] = {id = 110032, name = "王牌調度券", icon = "icon_goods_bidezhaomujuan", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "可以徵調真正的王牌駕駛員。\n「所謂王牌就是當她們出現在戰場上時所有人都會高呼她們的名字，然後在連綿的歡呼聲中看著她們輕鬆解決原本窮兇極惡的敵人。」\n「但即使是王牌，如果在錯誤的時間被派遣到錯誤的地方所帶來的結果也將是慘敗。」\n「所以請領航不要吝惜自己的熱情，更多地接近她們，瞭解她們，善待她們。」", group = 4102, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110033] = {id = 110033, name = "培訓意向書", icon = "icon_train", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "可以用於在特殊卡池「燧焰聯訓」進行十次調度。\n一份資料夾，裡面收納著十張培訓意向書。", group = 4103, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110034] = {id = 110034, name = "超越調度券", icon = "icon_goods_chaoyuezhaomujuan", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "可以徵調被冠以「超越」之名的駕駛員。\n「超越，即是不可複製的奇跡，駕駛員在某些方面突破了人類的極限，則可稱之為超越。」\n「與能被當作人類基石的王牌駕駛員不同，超越駕駛員是一種可能性。」\n「請領航不要以通常概念來定義超越駕駛員，她們強大並且弱小。」", group = 4103, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110035] = {id = 110035, name = "狂歡調度書", icon = "icon_goods_zhounianzhaomu", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "可以用於在特殊卡池「艾吉斯慶典」進行十次調度。\n「在如今這個時代，光是活著便已經是件幸事。讓我們為了今天而乾杯吧！」", group = 4103, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110036] = {id = 110036, name = "新年調度券", icon = "icon_goods_2024diaodu", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "可以用於在特殊卡池「螣蛇迎新歲」進行一次調度。\n「蛇的每次蜕皮，是一次更生，是一次新的开始。」", group = 4103, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
