[210034] = {id = 210034, name = "聯動紀念調度券", icon = "icon_liandongerxuanyi", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "僅可在【異世界來訪紀念！】調度卡池中使用，進行一次抽取。\n與異世界的邂逅，兩個世界的交匯所引發的奇蹟現象。", group = 4103, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110040] = {id = 110040, name = "精英演習券", icon = "icon_goods_datianruchangjuan-0", quality = 3, use = 1, fall = "4_100009_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "進入精英競技場所需的門票，使用後獲得一次進入精英競技場的資格。\n「教官會永遠記得那些從她手下闖出去的駕駛員。」\n「有誰退役了，有誰晉升了，有誰永遠留在戰場了。」\n「她把這些事情銘記心底。」", group = 3005, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = 500, "0", "0", "0"},
[110041] = {id = 110041, name = "新銳演習券", icon = "icon_goods_xiaotianruchangjuan-0", quality = 3, use = 1, fall = "4_100010_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "進入新銳競技場所需的門票，使用後獲得一次進入新銳競技場的資格。\n「跨過這道門檻，才能奔赴戰場。」\n「這是某位退役的駕駛員，為了降低新人駕駛員死亡率專門設立的競技場。」", group = 3006, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = 500, "0", "0", "0"},
[110050] = {id = 110050, name = "生存報告資料", icon = "icon_goods_juesejingyanshu-0", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "可提供1000點駕駛員經驗。\n「記載著簡單的戰鬥技巧，新銳駕駛員必看。」", group = 4004, itemstar = 0, describe = "0", costeffect = "0_1000", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110051] = {id = 110051, name = "晉升報告資料", icon = "icon_goods_juesejingyanshu-1", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "可提供5000點駕駛員經驗。\n「記載了一些比較複雜的戰鬥技巧，適合中堅的駕駛員提升自己。」", group = 4005, itemstar = 0, describe = "0", costeffect = "0_5000", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110052] = {id = 110052, name = "絕密報告資料", icon = "icon_goods_juesejingyanshu-2", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "可提供25000點駕駛員經驗。\n「珍貴的錄影，記載了■■■■■在第■■■次■■中的所有決策和行動。」", group = 4006, itemstar = 0, describe = "0", costeffect = "0_25000", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110060] = {id = 110060, name = "攻擊水晶Ⅲ型", icon = "icon_goods_juexing_gongji_2", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒攻擊型駕駛員能力的必要材料。\n「這群笨蛋——！！」\n「能跑掉一個是一個啊！」\n「只要我能讓這個怪物遠離後衛……」", group = 3039, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110061] = {id = 110061, name = "防衛水晶Ⅲ型", icon = "icon_goods_juexing_fangwei_2", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒防衛型駕駛員能力的必要材料。\n「我可以抗住。」\n「如果這是必要的犧牲。」\n「我必須站在大家的最前面！」", group = 3029, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110062] = {id = 110062, name = "火力水晶Ⅲ型", icon = "icon_goods_juexing_huoli_2", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒火力型駕駛員能力的必要材料。\n「……幫我撐一下，我有辦法解決它。」\n「從我的夥伴身邊滾開！！」", group = 3019, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110063] = {id = 110063, name = "支援水晶Ⅲ型", icon = "icon_goods_juexing_zhiyuan_2", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒支援型駕駛員能力的必要材料。\n「支援的能量已經耗空了……」\n「不對！我還有……！」\n「只要我把維繫存在的尼姆比斯液用來——」", group = 3009, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110070] = {id = 110070, name = "攻擊水晶Ⅱ型", icon = "icon_goods_juexing_gongji_1", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒攻擊型駕駛員能力的必要材料。\n「撤退！最後排的人先撤！我來拖一會！」\n「來不及了——準備迎接第一波攻擊！」", group = 3038, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110071] = {id = 110071, name = "防衛水晶Ⅱ型", icon = "icon_goods_juexing_fangwei_1", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒防衛型駕駛員能力的必要材料。\n「唔——！」\n「這種壓倒性的力量。」", group = 3028, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110072] = {id = 110072, name = "火力水晶Ⅱ型", icon = "icon_goods_juexing_huoli_1", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒火力型駕駛員能力的必要材料。\n「pong！——藝術！」\n「你們有看到嗎，剛剛那次爆破！」", group = 3018, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110073] = {id = 110073, name = "支援水晶Ⅱ型", icon = "icon_goods_juexing_zhiyuan_1", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒支援型駕駛員能力的必要材料。\n「我的同伴還在前線，我——」\n「要去支援她們！！」", group = 3008, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110080] = {id = 110080, name = "攻擊水晶Ⅰ型", icon = "icon_goods_juexing_gongji_0", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒攻擊型駕駛員能力的必要材料。\n「我竟然是隊長？！攻擊型駕駛員當隊長不太妥當吧？！」", group = 3037, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110081] = {id = 110081, name = "防衛水晶Ⅰ型", icon = "icon_goods_juexing_fangwei_0", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒防衛型駕駛員能力的必要材料。\n「請站在我身後。」", group = 3027, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110082] = {id = 110082, name = "火力水晶Ⅰ型", icon = "icon_goods_juexing_huoli_0", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒火力型駕駛員能力的必要材料\n「哈囉~我是負責火力壓制的駕駛員，為什麼出擊這麼慢？沒辦法，我得想要想辦法讓機子熱起來嘛~」", group = 3017, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110083] = {id = 110083, name = "支援水晶Ⅰ型", icon = "icon_goods_juexing_zhiyuan_0", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "tz_zz_zy_01", txt = "用於覺醒支援型駕駛員能力的必要材料。\n「我……我擅長支援和回復……」", group = 3007, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110090] = {id = 110090, name = "耀閃的殘響", icon = "icon_goods_jinengqianghua_2", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "用於強化訓練SSR駕駛員技能強度的珍貴材料。\n「個人的力量難以改變一場戰爭的局勢，但是總有一些特殊的駕駛員，我們可以對她們的成長報以期待。」\n「這份計劃書旨在培養那些能以一己之力終結戰爭的駕駛員。」\n「她們將會成為終結人類與原罪之間戰爭的利刃。」", group = 3202, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110091] = {id = 110091, name = "紺紫的殘響", icon = "icon_goods_jinengqianghua_1", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "用於強化訓練SR駕駛員技能強度的珍貴材料。\n「光是掌握技巧是遠遠不夠的。能擁有洞察全域的頭腦才能讓自己在戰場上進退自如。」", group = 3201, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110092] = {id = 110092, name = "湛蒼的殘響", icon = "icon_goods_jinengqianghua_0", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "用於強化訓練R駕駛員技能強度的珍貴材料。\n「一份安排得很充分的訓練計劃表，強度適中。」\n「可以預見，接受了這份訓練的新人們都將蛻變成功。」", group = 3200, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110093] = {id = 110093, name = "超越的殘響", icon = "icon_goods_jinengqianghua_tongyong", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "用於強化訓練超越型SSR駕駛員技能強度的珍貴材料。\n「下一次再失敗的話，世界就會真的毀滅，而我們與他所經歷的一切，都將成為無人銘記的過去。」\n「你與我們結下的羈絆，一次又一次的重置世界，不曾放棄這個世界，所以——」\n「首先是我，然後會是她們，超越的存在證明著，我的存在證明著——你的努力並非徒勞。」", group = 3202, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110100] = {id = 110100, name = "SSR駕駛員自選·壹", icon = "icon_goods_jiaosezixuan_2", quality = 4, use = 4, fall = "30_10000_1,30_10001_1,30_10021_1,30_11001_1,30_11002_1,30_11003_1,30_11008_1,30_11023_1,30_12003_1,30_12005_1,30_13009_1,30_13019_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "使用後可在一定範圍內任選一名駕駛員。\n「可選範圍：露露啦、朱利烏斯、辛西婭、愛麗絲、心紙、鈴木清風、艾希麗卡、曉夢、葉芙根尼婭、伊莉雅、艾伊瓦蒂、朝雾」", group = 4402, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110101] = {id = 110101, name = "SR駕駛員自選", icon = "icon_goods_jiaosezixuan_1", quality = 3, use = 4, fall = "30_10005_1,30_10006_1,30_10010_1,30_10011_1,30_10012_1,30_10014_1,30_10015_1,30_10016_1,30_10017_1,30_10018_1,30_11000_1,30_11006_1,30_11007_1,30_11011_1,30_11015_1,30_11016_1,30_11017_1,30_11018_1,30_11020_1,30_11028_1,30_11029_1,30_11030_1,30_12008_1,30_12009_1,30_12013_1,30_12015_1,30_13010_1,30_13020_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "使用後可在一定範圍內任選一名駕駛員。\n「可選範圍：華戀、棲琳、阿萊塔、弱水、格洛麗亞、科羅溫、索菲亞、安安、羅莎琳德、莉法、查麗莎、燕妮、莉迪婭、轟雷、鈴、黑羽、芙蘿拉、銀、卡洛琳、潔蘿、千陌、澄練、百里默默、瑪利亞、卡蓮、薇絲帕爾、渠、梅贝尔」", group = 4401, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110102] = {id = 110102, name = "R駕駛員自選", icon = "icon_goods_jiaosezixuan_0", quality = 2, use = 4, fall = "30_10002_1,30_10003_1,30_10007_1,30_10008_1,30_10013_1,30_11004_1,30_11009_1,30_11010_1,30_11019_1,30_12000_1,30_12002_1,30_12004_1,30_12007_1,30_12010_1,30_12012_1,30_12014_1,30_12016_1,30_13000_1,30_13001_1,30_13002_1,30_13003_1,30_13004_1,30_13006_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "使用後可在一定範圍內任選一名駕駛員。\n「可選範圍：漢克、森村鬼之介、海姬、多洛莉絲、莉莉絲、栗山青鸞、波琳娜、瓏、天天、金庫啦、不知火、花語、華夢、冥火、茱莉亞、西法麗絲、薩拉蒂、歐朵啦、弗蘭卡、蒂娜、克裡姆、彩華、瑩草」", group = 4400, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
