[110104] = {id = 110104, name = "SSR駕駛員自選·賀歲", icon = "icon_goods_jiaosezixuan_3", quality = 4, use = 4, fall = "30_10000_1,30_10001_1,30_10009_1,30_10021_1,30_10026_1,30_10030_1,30_10033_1,30_11001_1,30_11002_1,30_11003_1,30_11008_1,30_11023_1,30_11034_1,30_11035_1,30_11036_1,30_11043_1,30_12003_1,30_12005_1,30_12011_1,30_12020_1,30_12022_1,30_13005_1,30_13009_1,30_13019_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "使用後可在一定範圍內任選一名駕駛員。\n「可選範圍：露露啦、朱利烏斯、摩根勒菲、辛西婭、娜斯佳、法爾奈斯、柯朗、愛麗絲、心紙、鈴木清風、艾希麗卡、曉夢、羅德尼亞、桀派、普瑞席歐、米菈、葉芙根尼婭、伊莉雅、伽藍見、弗洛維拉、莱帕尼、熱尼亞、艾伊瓦蒂、朝雾」", group = 4402, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110105] = {id = 110105, name = "命運調度書", icon = "icon_role_sadame", quality = 4, use = 8, fall = "999_190000_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可隨機獲得一名常駐SSR駕駛員。\n一份被密封的部隊調度申請書，你無法判斷是誰的申請。\n未知有時候也代表驚喜，也許會出現意想不到的人。", group = 4402, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110106] = {id = 110106, name = "新年賀歲調度書", icon = "icon_role_sadame", quality = 4, use = 8, fall = "999_199003_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可隨機獲得一名SSR駕駛員。\n「隨機範圍：露露啦、朱利烏斯、D型b2、摩根勒菲、結束希、未来、辛西婭、法芙娜、摩、梅爾、娜斯佳、亞爾薇特、莉莉、法爾奈斯、奧菲莉亞、柯朗、洛基、查麗莎、轸宿四、赫洛卡、愛麗絲、心紙、鈴木清風、艾希麗卡、阿爾法、曉夢、今七實、千秋、羅德尼亞、桀派、普瑞席歐、斯卡蒂、多洛莉絲、海蘿、米菈、吠黎爾、佩佩塔、蕩漾兔、莉莉絲、波琳娜、葉芙根尼婭、伊莉雅、伽藍見、鈴、希夏、凱特琳、弗洛維拉、韶音、莱帕尼、莉法、熱尼亞、T型、伊莎貝拉、艾伊瓦蒂、梅莉雅、莉娜、朝雾、莫妮卡」", group = 4402, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
