[110150] = {id = 110150, name = "超越共鳴因子", icon = "icon_goods_factor_01", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "用於超限共鳴裝備的珍貴材料。\n「可促使幻化核心性能進一步提升的特殊試劑。由於產量有限，目前暫且無法大規模推廣使用。」", group = 3300, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110151] = {id = 110151, name = "幽晶花", icon = "icon_goods_wafer_01", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "逆愛的尼姆比斯碎片，在能源工廠中合成後用於超限共鳴裝備的必要材料。\n「據說祂身上每增添一朵花，就代表宇宙某處有一顆星球被原罪摧毀。若湊近聆聽，甚至能依稀聽到亡靈不甘而絕望的悲鳴聲。」", group = 3301, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110152] = {id = 110152, name = "幽晶石", icon = "icon_goods_crystal_01", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "逆愛的尼姆比斯結晶，用於超限共鳴裝備的珍貴材料。\n「從幽晶花中提煉出來的晶體，其中蘊含的尼姆比斯能源帶有極其牢固的逆愛標識，無法去除。」", group = 3302, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110153] = {id = 110153, name = "赤噬焰片", icon = "icon_goods_wafer_02", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "索貝克的尼姆比斯碎片，在能源工廠中合成後用於超限共鳴裝備的必要材料。\n「尚未覺醒意志的龐然大物，在指令驅使下，屠戮著所及之處一切生靈。隨著進程推進，它手中的利刃也越發紅豔，仿佛被鮮血詛咒了似的。」", group = 3303, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110154] = {id = 110154, name = "赤噬塊", icon = "icon_goods_crystal_02", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "索貝克的尼姆比斯結晶，用於超限共鳴裝備的珍貴材料。\n「從赤噬焰片中提煉出來的晶體，其中蘊含的尼姆比斯能源帶有極其牢固的索貝克標識，無法去除。」", group = 3304, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110155] = {id = 110155, name = "裂顎凶鯨", icon = "icon_goods_wafer_03", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "嫉妒的尼姆比斯碎片，在能源工廠中合成後用於超限共鳴裝備的必要材料。\n「從卵中強行孵化的嬰兒，剛睜眼便被催促著成長，但同母所生的姐姐卻能擁有完整的童年，母親的愛也被其霸佔。她咬牙看著姐姐，心生嫉妒。」", group = 3305, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110156] = {id = 110156, name = "裂顎凶齒", icon = "icon_goods_crystal_03", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "嫉妒的尼姆比斯結晶，用於超限共鳴裝備的珍貴材料。\n「從裂顎凶鯨中提煉出來的晶體，其中蘊含的尼姆比斯能源帶有極其牢固的嫉妒標識，無法去除。」", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
