[110212] = {id = 110212, name = "密托希瓦調度書", icon = "icon_juese_mituoxiwa_01", quality = 3, use = 5, fall = "30_13018_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員密托希瓦。\n一份部隊調度申請書，署名處簽寫著密托希瓦的名字。\n滴滴滴……您所通訊的對象不在服務區……", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110213] = {id = 110213, name = "摩根勒菲調度書", icon = "icon_juese_mogenlefei_01", quality = 4, use = 5, fall = "30_10009_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員摩根勒菲。\n一份部隊調度申請書，署名處簽寫著摩根勒菲的名字。\n領航，請露出笑容吧，那是我戰鬥的理由。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110214] = {id = 110214, name = "墨君調度書", icon = "icon_juese_mojun_01", quality = 3, use = 5, fall = "30_10028_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員墨君。\n一份部隊調度申請書，署名處簽寫著墨君的名字。\n還請不吝賜教。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110215] = {id = 110215, name = "萊帕尼調度書", icon = "icon_juese_laipani_01", quality = 4, use = 5, fall = "30_12022_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員萊帕尼。\n一份部隊調度申請書，署名處簽寫著萊帕尼的名字。\n希望我們從此之後都不會分開，不會走散。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110216] = {id = 110216, name = "羅德尼亞調度書", icon = "icon_juese_luodeniya_01", quality = 4, use = 5, fall = "30_11034_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員羅德尼亞。\n一份部隊調度申請書，署名處簽寫著羅德尼亞的名字。\n她本人預計會比調度書先到。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110217] = {id = 110217, name = "靜調度書", icon = "icon_juese_jing_01", quality = 3, use = 5, fall = "30_12001_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員靜。\n一份部隊調度申請書，署名處簽寫著靜的名字。\n簽名似乎有修改的痕跡，筆跡比印象中要更加工整。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110218] = {id = 110218, name = "娜斯佳調度書", icon = "icon_juese_nasijia_01", quality = 4, use = 5, fall = "30_10026_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員娜斯佳。\n一份部隊調度申請書，署名處簽寫著娜斯佳的名字。\n簽名用的塗料裏好像添加了容易讓人過敏的成分。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110219] = {id = 110219, name = "星井調度書", icon = "icon_juese_xingjin_01", quality = 3, use = 5, fall = "30_13021_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員星井。\n一份部隊調度申請書，署名處簽寫著星井的名字。\n今日的幸運色是紅色和紫色。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110220] = {id = 110220, name = "桀派調度書", icon = "icon_juese_jiepai_01", quality = 4, use = 5, fall = "30_11035_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員桀派。\n一份部隊調度申請書，署名處簽寫著桀派的名字。\n字寫得……嗯，很可愛。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110221] = {id = 110221, name = "斯缇菈調度書", icon = "icon_juese_sitila_01", quality = 3, use = 5, fall = "30_12023_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員斯缇菈。\n一份部隊調度申請書，署名處簽寫著斯缇菈的名字。\n與調度申請書一同寄來的，還有幾張美輪美奐的星空相片。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110222] = {id = 110222, name = "莉莉調度書", icon = "icon_juese_lili_01", quality = 4, use = 5, fall = "30_10029_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員莉莉。\n一份部隊調度申請書，署名處簽寫著莉莉的名字。\n以及三個可愛的貓爪圖案。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110223] = {id = 110223, name = "萊拉普斯調度書", icon = "icon_juese_lailapusi_01", quality = 3, use = 5, fall = "30_11031_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員萊拉普斯。\n一份部隊調度申請書，署名處簽寫著萊拉普斯的名字。\n名字筆法非常淩厲，莫非簽名的時候很生氣？", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110224] = {id = 110224, name = "千秋調度書", icon = "icon_juese_qianqiu_01", quality = 4, use = 5, fall = "30_11032_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員千秋。\n一份部隊調度申請書，署名處簽寫著千秋的名字。\n調度書是被剪成很多份後重新拼起來的。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110225] = {id = 110225, name = "星爍調度書", icon = "icon_juese_xingshuo_01", quality = 3, use = 5, fall = "30_11033_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員星爍。\n一份部隊調度申請書，署名處簽寫著星爍的名字。\n調度書被郵寄過來時並沒有寫地址，但還是準時送達了。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110226] = {id = 110226, name = "心紙調度書", icon = "icon_juese_xinzhi_01", quality = 4, use = 5, fall = "30_11002_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員心紙。\n一份部隊調度申請書，署名處簽寫著心紙的名字。\n神之名，不可知。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110227] = {id = 110227, name = "阿萊塔調度書", icon = "icon_juese_alaita_01", quality = 3, use = 5, fall = "30_10010_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員阿萊塔。\n一份部隊調度申請書，署名處簽寫著阿萊塔的名字。\n想要海妖小姐的吻。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110228] = {id = 110228, name = "露露啦調度書", icon = "icon_juese_lulula_01", quality = 4, use = 5, fall = "30_10000_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員露露啦。\n一份部隊調度申請書，署名處簽寫著露露啦的名字。\n上面還附帶了她在對戰平台上的UID。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110229] = {id = 110229, name = "梅貝爾調度書", icon = "icon_juese_meibeier_01", quality = 3, use = 5, fall = "30_13020_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員梅貝爾。\n一份部隊調度申請書，署名處簽寫著梅貝爾的名字。\n她的名字似乎沒寫完。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110230] = {id = 110230, name = "葉芙根尼婭調度書", icon = "icon_juese_yefugenniya_01", quality = 3, use = 5, fall = "30_12003_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員葉芙根尼婭。\n一份部隊調度申請書，署名處簽寫著葉芙根尼婭的名字。\n皺巴巴的紙，有很多水漬……沒錯，是汗水。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110231] = {id = 110231, name = "弱水調度書", icon = "icon_juese_ruoshui_01", quality = 3, use = 5, fall = "30_10011_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員弱水。\n一份部隊調度申請書，署名處簽寫著弱水的名字。\n使用的是秘密文字，類似盲文。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110232] = {id = 110232, name = "熱尼亞調度書", icon = "icon_juese_reniya_01", quality = 4, use = 5, fall = "30_13005_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員熱尼亞。\n一份部隊調度申請書，署名處簽寫著熱尼亞的名字。\n她的簽名看著讓人很安心。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110233] = {id = 110233, name = "莫莫卡調度書", icon = "icon_juese_momoka_01", quality = 3, use = 5, fall = "30_13014_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員莫莫卡。\n一份部隊調度申請書，署名處簽寫著莫莫卡的名字。\n摸上去有點冰涼。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110234] = {id = 110234, name = "莉迪婭調度書", icon = "icon_juese_lidiya_01", quality = 3, use = 5, fall = "30_11007_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員莉迪婭。\n一份部隊調度申請書，署名處簽寫著莉迪婭的名字。\n正文部分只寫了五個字——“大姐姐來啦！”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110235] = {id = 110235, name = "普瑞席歐調度書", icon = "icon_juese_puruixiou_01", quality = 4, use = 5, fall = "30_11036_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員普瑞席歐。\n一份部隊調度申請書，署名處簽寫著普瑞席歐的名字。\n字跡隨性潦草，顯然，她對簽名遠不及寫公式上心。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110236] = {id = 110236, name = "塞蕾希婭調度書", icon = "icon_juese_saileixiya_01", quality = 3, use = 5, fall = "30_11037_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員塞蕾希婭。\n一份部隊調度申請書，署名處簽寫著塞蕾希婭的名字。\n字跡工整乾淨，每一筆都如結晶。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110237] = {id = 110237, name = "伽藍見調度書", icon = "icon_juese_jialanjian_01", quality = 4, use = 5, fall = "30_12011_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員伽藍見。\n一份部隊調度申請書，署名處簽寫著伽藍見的名字。\n隱約可聞的海風氣息與飄搖的字體，暗示著那常年海上生活的經歷。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110238] = {id = 110238, name = "妍妍蘿調度書", icon = "icon_juese_yanyanluo_01", quality = 3, use = 5, fall = "30_11024_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員妍妍蘿。\n一份部隊調度申請書，署名處簽寫著妍妍蘿的名字。\n看起來臨時練過簽字，卻又難掩稚嫩的筆觸。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110239] = {id = 110239, name = "燕妮調度書", icon = "icon_juese_geluoliya_01", quality = 3, use = 5, fall = "30_11006_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員燕妮。\n一份部隊調度申請書，署名處簽寫著燕妮的名字。\n在這件事上，她似乎很積極。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110240] = {id = 110240, name = "法爾奈斯調度書", icon = "icon_juese_faernaisi_01", quality = 4, use = 5, fall = "30_10030_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員法爾奈斯。\n一份部隊調度申請書，署名處簽寫著法爾奈斯·蘭特的名字。\n隨信附贈了一顆散發芬芳的子彈。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110241] = {id = 110241, name = "卡芙卡調度書", icon = "icon_juese_kafuka_01", quality = 3, use = 5, fall = "30_11038_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員卡芙卡。\n一份部隊調度申請書，署名處簽寫著卡芙卡的名字。\n不，真的是卡芙卡的名字嗎？簡直是在塗鴉。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110242] = {id = 110242, name = "安安調度書", icon = "icon_juese_anan_01", quality = 3, use = 5, fall = "30_10016_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員安安。\n一份部隊調度申請書，署名處簽寫著安安的名字。\n“雖然安安是個笨蛋，但是安安會努力不拖大家後腿的！”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110243] = {id = 110243, name = "晓梦調度書", icon = "icon_juese_xiaomeng_01", quality = 4, use = 5, fall = "30_11023_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員晓梦。\n一份部隊調度申請書，署名處簽寫著曉夢的名字。\n閣下要曉夢來，曉夢便來了！", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110244] = {id = 110244, name = "亞爾薇特調度書", icon = "icon_juese_yaerweite_01", quality = 4, use = 5, fall = "30_10027_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員亞爾薇特。\n一份部隊調度申請書，署名處簽寫著亞爾薇特的名字。\n申請書？不……這是一封通知信。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110245] = {id = 110245, name = "多洛莉絲·偶像調度書", icon = "icon_juese_duoluolisiqingdian_01", quality = 4, use = 5, fall = "30_11040_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員多洛莉絲·偶像。\n一份部隊調度申請書，署名處簽寫著多洛莉絲的名字。\n多洛莉絲向你遞交的第二份調度書。離鳥終有歸巢日。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110246] = {id = 110246, name = "九十九環調度書", icon = "icon_juese_jiushijiuhuan_01", quality = 3, use = 5, fall = "30_13017_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員九十九環。\n一份部隊調度申請書，署名處簽寫著九十九環的名字。\n在名字的周圍畫滿了愛心，簡直就像想要將這份心情透過名字傳達給你。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110247] = {id = 110247, name = "克裏斯蒂娜調度書", icon = "icon_juese_kelisidina_01", quality = 3, use = 5, fall = "30_10032_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員克里斯蒂娜。\n一份部隊調度申請書，署名處簽寫著克里斯蒂娜的名字。\n申請書上有一圈明顯的咖啡漬。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110248] = {id = 110248, name = "薇絲帕爾調度書", icon = "icon_juese_weisipaer_01", quality = 3, use = 5, fall = "30_12015_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員薇絲帕爾。\n一份部隊調度申請書，署名處簽寫著薇絲帕爾的名字。\n優雅的多瑙之花已經蒞臨你的指揮室。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110249] = {id = 110249, name = "莉法調度書", icon = "icon_juese_lifa_01", quality = 3, use = 5, fall = "30_10018_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員莉法。\n一份部隊調度申請書，署名處簽寫著莉法的名字。\n“主人，請問您今天需要我的服侍嗎？”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110250] = {id = 110250, name = "柯朗調度書", icon = "icon_juese_kelang_01", quality = 4, use = 5, fall = "30_10033_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員柯朗。\n一份部隊調度申請書，署名處簽寫著柯朗的名字。\n與其說是名字……S52？這不是她的代號嗎？", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110251] = {id = 110251, name = "織女星調度書", icon = "icon_juese_zhinvxing_01", quality = 3, use = 5, fall = "30_11041_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員織女星。\n一份部隊調度申請書，署名處簽寫著織女星的名字。\n相比於“織女星”，她簽在其他文檔上的“蘇亞娜”明顯更為美觀。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110252] = {id = 110252, name = "華戀調度書", icon = "icon_juese_hualian_01", quality = 3, use = 5, fall = "30_10005_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員華戀。\n一份部隊調度申請書，署名處簽寫著華戀的名字。\n“小生這一腳，請問閣下接得住嗎？”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110253] = {id = 110253, name = "愛麗絲調度書", icon = "icon_juese_ailisi_01", quality = 4, use = 5, fall = "30_11001_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員愛麗絲。\n一份部隊調度申請書，署名處簽寫著愛麗絲的名字。\n“這一劍，接得住嗎？”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110254] = {id = 110254, name = "赫莉調度書", icon = "icon_juese_heli_01", quality = 3, use = 5, fall = "30_10035_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員赫莉。\n一份部隊調度申請書，署名處簽寫著赫莉的名字。\n調度文檔中夾帶著一張赫莉的名片，“24小時外送服務，隨叫隨到，請聯絡————————”。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110255] = {id = 110255, name = "海蘿調度書", icon = "icon_juese_hailuo_01", quality = 4, use = 5, fall = "30_11042_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員海蘿。\n一份部隊調度申請書，署名處簽寫著海蘿的名字。\n她親自把這份調度書拍到了你的桌子上，並得意地拍了拍胸口。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110256] = {id = 110256, name = "洛基調度書", icon = "icon_juese_luoji_01", quality = 4, use = 5, fall = "30_10034_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員洛基。\n一份部隊調度申請書，署名處簽寫著洛基的名字。\n與調度書一同送來的，還有洛基的命。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110257] = {id = 110257, name = "星爍·星變奇蹟調度書", icon = "icon_juese_wuzhuangxingshuo_01", quality = 4, use = 5, fall = "30_14000_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員星爍·三億分之一的偶然。\n一份部隊調度申請書，署名處簽寫著星爍的名字。\n相遇與分別，這是人生的主旋律，從未改變。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110258] = {id = 110258, name = "鈴木清風調度書", icon = "icon_juese_lingmuqingfeng_01", quality = 4, use = 5, fall = "30_11003_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員鈴木清風。\n一份部隊調度申請書，署名處簽寫著鈴木清風的名字。\n風林火山的風，日後將如清風般環繞在你身旁，給予你母親的溫柔。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110259] = {id = 110259, name = "棲琳調度書", icon = "icon_juese_xilin_01", quality = 3, use = 5, fall = "30_10006_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員棲琳。\n一份部隊調度申請書，署名處簽寫著棲琳的名字。\n在這份調度書之後的另一份工作申請表——成為你的新聞記者。這是她為自己找到的新工作。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110260] = {id = 110260, name = "米菈調度書", icon = "icon_juese_mila_01", quality = 4, use = 5, fall = "30_11043_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員米菈。\n一份部隊調度申請書，署名處簽寫著米菈的名字。\n隨贈一封筆跡雅緻、遣詞正式的邀約函。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110261] = {id = 110261, name = "潔蘿調度書", icon = "icon_juese_jieluo_01", quality = 4, use = 5, fall = "30_11028_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員潔蘿。\n一份部隊調度申請書，署名處簽寫著潔蘿的名字。\n散發著勃勃的生機。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110262] = {id = 110262, name = "朝霧調度書", icon = "icon_juese_zhaowu_01", quality = 4, use = 5, fall = "30_13019_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員朝霧。\n一份部隊調度申請書，署名處簽寫著朝霧的名字。\n據說朝霧當時的表情就像在簽署一份病危通知單。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110263] = {id = 110263, name = "澄練調度書", icon = "icon_juese_chenlian_01", quality = 3, use = 5, fall = "30_11030_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員澄練。\n一份部隊調度申請書，署名處簽寫著澄練的名字。\n我的職責是見證歷史，記錄未來。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
