[110265] = {id = 110265, name = "卡蓮調度書", icon = "icon_juese_kalian_01", quality = 3, use = 5, fall = "30_12013_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員卡莲。\n一份部隊調度申請書，署名處簽寫著卡蓮的名字。\n老師，之後請多指教。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
