[110274] = {id = 110274, name = "希夏調度書", icon = "icon_juese_xixia_01", quality = 4, use = 5, fall = "30_12018_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員希夏。\n一份新的AVG藍圖申請書，署名處簽寫著希夏的名字。\n字跡的結構清晰整齊，映出她對築橋的執著。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
