[110277] = {id = 110277, name = "莉娜調度書", icon = "icon_juese_lina_01", quality = 4, use = 5, fall = "30_13015_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員莉娜。\n一份部隊調度申請書，署名處簽寫著莉娜的名字。\n在你簽下這份調度書的那一瞬間，超級假面人1號忽然出現在你背後，然後你就被帶去和她一起捍衛正義了。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110278] = {id = 110278, name = "D型b2調度書", icon = "icon_juese_b2_01", quality = 4, use = 5, fall = "30_10004_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員D型b2。\n一份部隊調度申請書，署名處簽寫著D型b2的名字。\n此申請書僅是走個程式，畢竟除了領航還有誰能操控D型b2呢？", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110279] = {id = 110279, name = "瑪利亞調度書", icon = "icon_juese_maliya_01", quality = 3, use = 5, fall = "30_12009_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員瑪利亞。\n一份部隊調度申請書，署名處簽寫著瑪利亞的名字。\n“我已經迫不及待地想要擁抱小弟弟了。”，隨調度書寄來了一封熱情洋溢的信。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110280] = {id = 110280, name = "黑羽調度書", icon = "icon_juese_heiyu_01", quality = 3, use = 5, fall = "30_11016_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員黑羽。\n一份部隊調度申請書，署名處簽寫著黑羽的名字。\n趁著你閉眼伸懶腰的時間，忽然出現在你桌上的調度書，你嘗試呼喚黑羽的名字，她果然從身後抱住你了。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110281] = {id = 110281, name = "伊莎貝拉調度書", icon = "icon_juese_yishabeila_01", quality = 4, use = 5, fall = "30_13008_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員伊莎貝拉。\n一份部隊調度申請書，署名處簽寫著伊莎貝拉的名字。\n署名字體特意經過設計，筆畫拐角處均如星芒閃爍。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110282] = {id = 110282, name = "伊莉雅調度書", icon = "icon_juese_yiliya_01", quality = 4, use = 5, fall = "30_12005_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員伊莉雅。\n一份部隊調度申請書，署名處簽寫著伊莉雅的名字。\n字跡像是火焰，可以聞到金屬和木頭的焦味。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110283] = {id = 110283, name = "蕩漾兔調度書", icon = "icon_juese_dangyangtu_01", quality = 4, use = 5, fall = "30_11047_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員蕩漾兔。\n一份部隊調度申請書，署名處簽寫著蕩漾兔的名字。\n十分具有偶像派頭的簽名，圖案可愛但卻使人看不清名字。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110284] = {id = 110284, name = "千陌調度書", icon = "icon_juese_qianmo_01", quality = 3, use = 5, fall = "30_11029_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員千陌。\n一份部隊調度申請書，署名處簽寫著千陌的名字。\n名字的每一條直線，每一條弧線，都是完美的。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110285] = {id = 110285, name = "吠黎爾調度書", icon = "icon_juese_fenlier_01", quality = 4, use = 5, fall = "30_11045_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員吠黎爾。\n一份身份證明，署名處簽寫著吠黎爾的名字。\n只有待在你的身邊B17才會安穩地入眠。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110286] = {id = 110286, name = "銀調度書", icon = "icon_juese_yin_01", quality = 3, use = 5, fall = "30_11018_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員銀。\n一份部隊調度申請書，署名處簽寫著銀的名字。\n被馴服的銀白野獸也能稱作真正的戰士嗎？", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110287] = {id = 110287, name = "羅莎琳德調度書", icon = "icon_juese_luoshalinde_01", quality = 3, use = 5, fall = "30_10017_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員羅莎琳德。\n一份部隊調度申請書，署名處簽寫著羅莎琳德的名字。\n“來協助本小姐成為真正的貴族吧。”這麼說著的羅莎琳德，已經頗具貴族風範了。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110288] = {id = 110288, name = "凱特琳調度書", icon = "icon_juese_kaiteling_01", quality = 4, use = 5, fall = "30_12019_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員凱特琳。\n一份部隊調度申請書，署名處簽寫著凱特琳的名字。\n我有預感，這不是最後一次。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110289] = {id = 110289, name = "梅爾調度書", icon = "icon_juese_meier_01", quality = 4, use = 5, fall = "30_10025_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員梅爾。\n一份部隊調度申請書，署名處簽寫著梅爾的名字。\n陪在你身邊才是真的自由。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110290] = {id = 110290, name = "科羅溫調度書", icon = "icon_juese_keluowen_01", quality = 3, use = 5, fall = "30_10014_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員科羅溫。\n一份部隊調度申請書，署名處簽寫著科羅溫的名字。\n離家的金雀何時重回堂皇的鳥籠。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110291] = {id = 110291, name = "王女調度書", icon = "icon_juese_wangnv_01", quality = 3, use = 5, fall = "30_11022_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員王女。\n一份身份證明，署名處簽寫著斯卡蒂的名字。\n“好了，從現在開始世界上就有兩個斯卡蒂了。”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110292] = {id = 110292, name = "莉莉絲·泳装調度書", icon = "icon_juese_yongzhuanglilisi_01", quality = 4, use = 5, fall = "30_11048_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員莉莉絲·泳装。\n一份海濱樂園度假申請書，署名處簽寫著莉莉絲的名字。\n這次海濱樂園之行最晚遞交的申請書，看來莉莉絲掙扎到了最後。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110293] = {id = 110293, name = "弗蘭卡·泳装調度書", icon = "icon_juese_yongzhuangfulanka_01", quality = 3, use = 5, fall = "30_12024_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員弗蘭卡。\n一份海濱樂園度假申請書，署名處簽寫著弗蘭卡的名字。\n怪不得弗蘭卡這幾天見到你目光閃爍，原來是考慮這件事。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110294] = {id = 110294, name = "奧菲莉亞·星之君主調度書", icon = "icon_juese_spaofeiliya_01", quality = 4, use = 5, fall = "30_14002_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員奧菲莉亞·星之君主。\n一份新的AVG藍圖申請書，署名處簽寫著奧菲莉亞的名字。\n從顫抖的筆跡中可以看出奧菲莉亞的心很不平靜。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110295] = {id = 110295, name = "未来·泳装調度書", icon = "icon_juese_weilai_01", quality = 4, use = 5, fall = "30_10020_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員未来·泳装。\n一份部隊實習申請書，署名處簽寫著未來的名字。\n“女主角就該有根據環境改變的不同的戰鬥服裝。”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110296] = {id = 110296, name = "阿爾法調度書", icon = "icon_juese_aerfa_01", quality = 4, use = 5, fall = "30_11012_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員阿爾法。\n一份部隊調度申請書，署名處簽寫著阿爾法的名字。\n筆跡斷斷續續，對於一個機器人來說不該如此。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110297] = {id = 110297, name = "佩佩塔調度書", icon = "icon_juese_peipeita_01", quality = 4, use = 5, fall = "30_11046_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員佩佩塔。\n一份部隊調度申請書，署名處簽寫著佩佩塔的名字。\n她居然是衝到你面前來簽字的。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110298] = {id = 110298, name = "芙蘿拉調度書", icon = "icon_juese_fuluola_01", quality = 3, use = 5, fall = "30_11017_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員芙蘿拉。\n一份部隊調度申請書，署名處簽寫著芙蘿拉的名字。\n多瑙支部最忠誠的駕駛員向您報導。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110299] = {id = 110299, name = "法芙娜調度書", icon = "icon_juese_fafuna_01", quality = 4, use = 5, fall = "30_10022_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員法芙娜。\n一份部隊調度申請書，署名處簽寫著法芙娜的名字。\n紙上似乎沾了些灑落的糖粒。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110300] = {id = 110300, name = "歐朵啦調度書", icon = "icon_juese_ouduola_01", quality = 2, use = 5, fall = "30_13000_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得R駕駛員歐朵啦。\n一份部隊調度申請書，署名處簽寫著歐朵啦的名字。\n在簽署好調度書之後，她靠在你的身上睡著了。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110301] = {id = 110301, name = "今七實調度書", icon = "icon_juese_qishi_01", quality = 4, use = 5, fall = "30_11027_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員今七實。\n一份部隊調度申請書，署名處簽寫著今七實的名字。\n簽寫著“imananami”，雖說確實是今七實，但也有可能是反過來簽名。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110302] = {id = 110302, name = "阿爾泰婭調度書", icon = "icon_juese_aertaiya_01", quality = 3, use = 5, fall = "30_11049_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員阿爾泰婭。\n一份部隊調度申請書，署名處簽寫著阿爾泰婭的名字。\n阿爾泰婭·維斯，以及塞缪。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110303] = {id = 110303, name = "菲琳調度書", icon = "icon_juese_feiling_01", quality = 3, use = 5, fall = "30_12025_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員菲琳·布蘭妮。\n一份部隊調度申請書，署名處簽寫著菲琳·布蘭妮的名字。\n接受自己的普通和平庸，然後帶上武器去迎接明天。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110304] = {id = 110304, name = "莉法·骑行服調度書", icon = "icon_juese_lifajiche_01", quality = 4, use = 5, fall = "30_12026_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員莉法·骑行服。\n一份部隊調度申請書，署名處簽寫著莉法的名字。\n在方舟內開著機車橫衝直撞地帶著調度申請書交給你的颯爽女僕。但是為什麼？在方舟內？？開機車？？？", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110305] = {id = 110305, name = "摩調度書", icon = "icon_juese_mo_01", quality = 4, use = 5, fall = "30_10023_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員摩。\n一份部隊調度申請書，署名處簽寫著摩的名字。\n摩親自來提交申請書之後，方舟內開始傳出惡魔、山羊人的流言。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110306] = {id = 110306, name = "軫宿四調度書", icon = "icon_juese_zhensusi_01", quality = 4, use = 5, fall = "30_10037_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員軫宿四。\n一份部隊調度申請書，署名處簽寫著軫宿四的名字。\n有多處修改痕跡，顯然本人對這個“名字”很不熟悉。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
