[110316] = {id = 110316, name = "未来·情人节調度書", icon = "icon_juese_qrjweilai_01", quality = 4, use = 5, fall = "30_12028_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員未來·情人节。\n一份新的AVG藍圖申請書，署名處簽寫著未來的名字。\n驕傲的、淘氣的、難纏的小鬼開心地把這份申請遞交給你，如果拒絕她的話，她一定會哭很久吧？", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
