[110319] = {id = 110319, name = "小朱利初號機調度書", icon = "icon_juese_xiaozhuli_01", quality = 4, use = 5, fall = "30_10040_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "领取后可获得SSR驾驶员小朱利初号机。\n一份部队调度申请书，署名处签写着红博士的名字。\n“她说想到你那边去。”红博士说着签下来这份调度书。……究竟是谁想到我这边？红博士？red？还是说……", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
