[110342] = {id = 110342, name = "米夏調度書", icon = "icon_juese_mixia_01", quality = 4, use = 5, fall = "30_11058_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員米夏。\n一份新部隊的委任申請書，署名處簽寫著米夏的名字。\n除了鼓足幹勁去做，也沒有別的選擇了。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110343] = {id = 110343, name = "伊妲調度書", icon = "icon_juese_yida_01", quality = 3, use = 5, fall = "30_12032_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員伊妲。\n一份部隊調度申請書，署名處簽寫著伊妲的名字。\n為防止申請書被人偽造，我定下了你我都知道的暗號。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110344] = {id = 110344, name = "格洛麗亞·球服調度書", icon = "icon_juese_geluoliyaqiufu_01", quality = 4, use = 5, fall = "30_12033_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員格洛麗亞·球服。\n一份部隊調度申請書，署名處簽寫著格洛麗亞的名字。\n“領航先生，今天的訓練也麻煩您了。”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110345] = {id = 110345, name = "葉芙根尼婭·D.F.A調度書", icon = "icon_juese_yefugenniyadfa_01", quality = 4, use = 5, fall = "30_12034_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員葉芙根尼娅·D.F.A。\n一份部隊調度申請書，署名處簽寫著葉芙根尼娅的名字。\n焕然一新的外表，一模一样的内在。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110346] = {id = 110346, name = "伊斯卡拉·心焰再明調度書", icon = "icon_juese_spyisikala_01", quality = 4, use = 5, fall = "30_14007_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員伊斯卡拉·心焰再明。\n一份部隊調度申請書，署名處板板正正地写着伊斯卡拉的全名。\n做了再次出发的决定，就别随便停下。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110347] = {id = 110347, name = "戈露卡調度書", icon = "icon_juese_geluka_01", quality = 3, use = 5, fall = "30_11060_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員戈露卡。\n一份部隊調度申請書，署名處簽寫著戈露卡的名字。\n从笔迹上看，她非常努力地想把这个名字写好。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110348] = {id = 110348, name = "特薇爾達調度書", icon = "icon_juese_teweierda_01", quality = 4, use = 5, fall = "30_10045_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員特薇爾達。\n一份部隊調度申請書，署名處簽寫著特薇爾達的名字。\n本職之外的工作她也會幫忙，但全都會按加班標準上報。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110349] = {id = 110349, name = "法爾奈斯·禮服調度書", icon = "icon_juese_faernaisilifu_01", quality = 4, use = 5, fall = "30_13027_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員法爾奈斯·禮服。\n一份部隊調度申請書，署名處簽寫著法爾奈斯的名字。\n“答應好的事情就要做到底，這是應有的禮儀，領航。”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110350] = {id = 110350, name = "百里默默調度書", icon = "icon_juese_bailimomo_01", quality = 3, use = 5, fall = "30_12008_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SR駕駛員百里默默。\n一份部隊調度申請書，署名處簽寫著百里默默的名字。\n“默默和姐姐们已经准备好了！”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110351] = {id = 110351, name = "山城戀調度書", icon = "icon_juese_shanchenglian_01", quality = 4, use = 5, fall = "30_14008_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員山城戀。\n一份部隊調度申請書，署名處籤寫著山城戀的名字。\n小隊的名字……日萬凜已經取過了嗎？", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110352] = {id = 110352, name = "東風舞希調度書", icon = "icon_juese_dongfengwuxi_01", quality = 4, use = 5, fall = "30_10046_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員東風舞希。\n一份部隊調度申請書，署名處籤寫著東風舞希的名字。\n以小隊爲單位來行動，這就是你們的編制嗎？", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110353] = {id = 110353, name = "蝦夷夜雲調度書", icon = "icon_juese_xiayiyeyun_01", quality = 4, use = 5, fall = "30_12035_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員蝦夷夜雲。\n一份部隊調度申請書，署名處簽寫著蝦夷夜雲的名字。\n不錯呢，即使在異世界也有魔防隊嗎？", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110354] = {id = 110354, name = "上運天美羅調度書", icon = "icon_juese_shangyuntianmeiluo_01", quality = 4, use = 5, fall = "30_11061_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員上運天美羅。\n一份部隊調度申請書，署名處簽寫著上運天美羅的名字。\n叫什麼都行吧，無所謂啦。", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110355] = {id = 110355, name = "朱利烏斯·私服調度書", icon = "icon_juese_zhusiwusisifu_01", quality = 4, use = 5, fall = "30_11062_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可獲得SSR駕駛員朱利烏斯·私服。\n一份新的AVG藍圖申請書，署名處簽寫著朱利烏斯的名字。\n“那個……我覺得把這身裝束投入實戰還是有點……”", group = 6000, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
