[110902] = {id = 110902, name = "青雲之志·一定能找到", icon = "icon_role_sadame", quality = 4, use = 8, fall = "999_199999_1", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "領取後可隨機獲得一名SSR駕駛員。\n「隨機範圍：東日萬凜、大川村寧」", group = 4402, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110800] = {id = 110800, name = "友情記憶體α", icon = "icon_goods_Blueprint_01", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【友情】的燃料。\n以友情高舉前進的旗幟。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110801] = {id = 110801, name = "友情記憶體β", icon = "icon_goods_Blueprint_02", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【友情】的燃料。\n防衛型駕駛員因【友情】而變得更加強大，正因為有絕對要保護的人，所以才會熠熠生輝。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110802] = {id = 110802, name = "友情記憶體γ", icon = "icon_goods_Blueprint_03", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【友情】的燃料。\n友情啊……是一種柔軟卻堅韌的東西。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110803] = {id = 110803, name = "友情記憶體δ", icon = "icon_goods_Blueprint_04", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【友情】的燃料。\n為了未來，合而為一。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110804] = {id = 110804, name = "勇氣記憶體α", icon = "icon_goods_Blueprint_05", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【勇氣】的燃料。\n以勇氣踏出最初的第一步。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110805] = {id = 110805, name = "勇氣記憶體β", icon = "icon_goods_Blueprint_06", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【勇氣】的燃料。\n如若用某種特質來形容攻擊型駕駛員的話，那應該就是【勇氣】這個詞了。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110806] = {id = 110806, name = "勇氣記憶體γ", icon = "icon_goods_Blueprint_07", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【勇氣】的燃料。\n勇氣誕生於人類最脆弱的一刻。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110807] = {id = 110807, name = "勇氣記憶體δ", icon = "icon_goods_Blueprint_08", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【勇氣】的燃料。\n為了未來，合而為一。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110808] = {id = 110808, name = "智慧記憶體α", icon = "icon_goods_Blueprint_09", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【智慧】的燃料。\n以智慧之光奠定前路。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110809] = {id = 110809, name = "智慧記憶體β", icon = "icon_goods_Blueprint_10", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【智慧】的燃料。\n最瘋狂的【智慧】締造而出的文明猛獸，駕馭著它的同樣是聰慧的孤高之人。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110810] = {id = 110810, name = "智慧記憶體γ", icon = "icon_goods_Blueprint_11", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【智慧】的燃料。\n智慧不是知識的堆砌", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110811] = {id = 110811, name = "智慧記憶體δ", icon = "icon_goods_Blueprint_12", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【智慧】的燃料。\n為了未來，合而為一。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
[110812] = {id = 110812, name = "純真記憶體α", icon = "icon_goods_Blueprint_13", quality = 2, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "人類希望的藍圖，注入名為【純真】的燃料。\n以純真維繫旅途的喜樂。", group = 3306, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
