[120000] = {id = 120000, name = "繪本“哥哥與我”", icon = "icon_goods_qk_1", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "吉雅把做好的巧克力小人鑲嵌在“書本”外貌的禮盒中，攤開書會見到塗鴉風格的巧克力鑲嵌在禮盒中。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120001] = {id = 120001, name = "石中劍", icon = "icon_goods_qk_2", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "刺在巧克力石頭中的巧克力劍。精雕細琢的劍柄上可以反射出光輝。劍柄上銘刻著朱利烏斯家的家徽。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120002] = {id = 120002, name = "查麗莎等身巧克力", icon = "icon_goods_qk_3", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "像一座紀念偉人的雕塑，查麗莎製作了自己的等身巧克力送給領航。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
