[120009] = {id = 120009, name = "五葉草標本", icon = "icon_goods_qk_10", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "你給吉雅的情人節禮物，被她保存在你們的小屋中，由你們共同守護。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120010] = {id = 120010, name = "愛心滿滿巧克力", icon = "icon_goods_qk_11", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "多洛莉絲的情人節禮物，溫馨中帶著體貼，多洛莉絲心中始終掛念著你。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120011] = {id = 120011, name = "捶背券", icon = "icon_goods_qk_12", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "八雲的情人節禮物，說是捶背券，實際上提什麼要求她都不會拒絕。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120012] = {id = 120012, name = "無數世界線的唯一解", icon = "icon_goods_qk_13", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "九十九環的情人節禮物，據她所說，她為了這塊巧克力差點把世界毀滅了……從“預知未來”的超能力者口中聽到這句話實在是太恐怖了。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120013] = {id = 120013, name = "芙蘿拉完美人偶", icon = "icon_goods_qk_14", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "芙蘿拉的情人節禮物，隨著完美人偶一起送來的還有很多製作過程中的失敗品。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120014] = {id = 120014, name = "一見鍾情巧克力", icon = "icon_goods_qk_15", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "紅博士的情人節禮物，這是惡魔的饋贈，根據你的抉擇一念天堂一念地獄。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120015] = {id = 120015, name = "寶石裏面都是心意！", icon = "icon_goods_qk_16", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "羅莎琳德的情人節禮物，她小心翼翼想要給你驚喜的樣子就像寶石一樣耀眼。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120016] = {id = 120016, name = "巨大宇宙未來抱枕", icon = "icon_goods_qk_17", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "未來的情人節禮物，“想我的時候就看看這個抱枕吧”未來是這麼說的，於是你決定把抱枕拿來墊一墊背。\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
[120017] = {id = 120017, name = "釘頭七箭書", icon = "icon_goods_qk_18", quality = 4, use = 1, fall = "4_100001_50", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "曉夢的情人節禮物，被害者沒有反抗能力，就連大羅神仙亦難逃此厄……曉夢保證百分之百有效……真是危險品，封印！\n使用後可恢復50點體力。", group = 4003, itemstar = 0, describe = "0", costeffect = "0", sort = 2, giftappear = 0, numlimt = -1, "0", "0", "0"},
