[999997] = {id = 999997, name = "聯動超越調度券", icon = "icon_goods_liandongchaoyuezhaomujuanA_coll", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "可以徵調被冠以「超越」之名的駕駛員。\n「超越，即是不可複製的奇跡，駕駛員在某些方面突破了人類的極限，則可稱之為超越。」\n「與能被當作人類基石的王牌駕駛員不同，超越駕駛員是一種可能性。」\n「請領航不要以通常概念來定義超越駕駛員，她們強大並且弱小。」", group = 4103, itemstar = 0, describe = "0", costeffect = "0", sort = 3, giftappear = 0, numlimt = -1, "0", "0", "0"},
